import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR 与最终实施原则","description":"","frontmatter":{"title":"ADR 与最终实施原则"},"headers":[],"relativePath":"zh/guide/adr-principles.md","filePath":"zh/guide/adr-principles.md","lastUpdated":0}`),a={name:`zh/guide/adr-principles.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_17-adr-必须记录的架构决策" tabindex="-1">17. ADR：必须记录的架构决策 <a class="header-anchor" href="#_17-adr-必须记录的架构决策" aria-label="Permalink to “17. ADR：必须记录的架构决策”">​</a></h1><p>以下决策需要以 ADR 形式落档：</p><ol><li>为什么选择 Rust。</li><li>为什么第一版采用外部进程插件。</li><li>为什么选择 JSON-RPC over stdio。</li><li>为什么采用 Resource + Dependency Graph。</li><li>为什么依赖图由 Core Engine 协调。</li><li>为什么动作结果必须经过独立验证。</li><li>为什么使用 SQLite。</li><li>为什么恢复动作前必须持久化关键状态。</li><li>为什么通知系统与恢复引擎解耦。</li><li>为什么 Dashboard 默认关闭。</li><li>为什么 P0 只实现 Process 和 Exec Probe。</li><li>为什么不允许未经授权的高风险网络动作。</li><li>为什么未知执行结果不能直接重试。</li><li>为什么禁止普通依赖图循环。</li></ol><p>ADR 必须记录背景、决策、替代方案、优缺点和后续影响。</p><ol start="15"><li>为什么核心维护内部集成工具箱（HTTP/RPC/SSH/探测原语），插件只是规则层。</li></ol><p><strong>背景</strong>：随着探测与恢复动作覆盖 HTTP、RPC、SSH、服务控制等传输/协议，若每个插件各自实现传输，安全硬化（TLS 校验、SSRF 防护、SSH 主机密钥验证、超时/重试/取消、凭据安全读取）会被 N 份实现稀释，且无法统一强制。</p><p><strong>决策</strong>：核心收敛一组“内部集成工具”作为能力执行器（HTTP 客户端、RPC 客户端、SSH 客户端、进程/服务/磁盘/网络连通性探测、受控命令执行、重启控制），以 Capability（十一项元数据）+ OperationParams（参数化输入）对外声明。插件与内置能力走同一张派发表：内置能力由核心进程内执行器直接执行，插件声明的能力由插件子进程执行。插件不再自行实现底层传输，只提供能力声明与规则逻辑（目标、参数、决策、验证）。</p><p><strong>替代方案</strong>：保持插件自包含、各自实现传输。缺点：重复的传输实现、安全硬化易被绕过、插件体积与攻击面大。</p><p><strong>优缺点</strong>：集中硬化一次、语义统一（超时/取消/预算/审计）、插件变薄；代价是核心的工具面需要维护，插件自由度下降（不再能任意实现自定义协议）。</p><p><strong>后续影响</strong>：P2 平台适配器（systemd/launchd/SCM、网络接口/路由/DNS）作为工具执行器注册进同一注册表；Webhook 通知渠道复用工具箱 HTTP 客户端（含 SSRF 防护）；Python 出向绑定暴露的是工具调用而非任意执行。</p><hr><h1 id="_18-最终实施原则" tabindex="-1">18. 最终实施原则 <a class="header-anchor" href="#_18-最终实施原则" aria-label="Permalink to “18. 最终实施原则”">​</a></h1><p>Custos 的成功标准不是能够监控多少种服务，而是遇到真实故障时，能够正确判断依赖、执行适当的恢复动作、验证结果，并留下完整记录。</p><p>整个系统应遵循：</p><p><strong>资源负责描述对象，依赖负责描述前置条件，插件负责提供能力，策略负责决定动作，核心引擎负责协调执行，验证负责判定结果，持久化负责保留事实，通知负责传递事件，Dashboard 负责可选展示。</strong></p><p>第一阶段必须先把核心恢复闭环、依赖语义、持久化和失败处理实现正确。后续再逐步加入 Windows 网络恢复、代理、Cloudflare Tunnel、OpenClash 和其他平台能力。</p><p>不要一次性实现所有插件，也不要提前构建复杂的 Dashboard 或插件市场。</p><p>先用最小但完整的恢复闭环证明架构，再根据真实部署中无法处理的故障逐步扩展。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};